namespace sv_6776aefa98204353936ddd8de9a5562d.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies
/// all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastCount;

    public int LowStockCount => _lastCount;

    /// <summary>
    /// Fired from a background thread (PeriodicTimer) — subscribers
    /// MUST wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by a polling component to refresh the count and broadcast
    /// the update to every subscriber.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertCountChanged = null;
    }
}

