@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService Alerts
@implements IAsyncDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p class="lead">
    Viewing: <strong>@Warehouse.CurrentWarehouse.Name</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4">
                    <AlertBadge />
                </p>
                <p class="text-muted">
                    Items below minimum level &middot; refreshes every 10&nbsp;s
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Kick off the initial fetch + start the polling loop.
            await Alerts.RefreshAsync(Warehouse.CurrentWarehouseId);
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await Alerts.RefreshAsync(Warehouse.CurrentWarehouseId);
        }
    }

    private async Task OnWarehouseChanged()
    {
        // Restart polling for the newly selected warehouse.
        await _cts.CancelAsync();
        _cts.Dispose();
        _cts = new CancellationTokenSource();

        await Alerts.RefreshAsync(Warehouse.CurrentWarehouseId);
        StateHasChanged();
        _ = PollAsync(_cts.Token);
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;

        await _cts.CancelAsync();
        _cts.Dispose();
    }
}

